def find_comps(g, skip=(0,5)):
    h=len(g); w=len(g[0]); found=set(); out=[]
    for r in range(h):
        for c in range(w):
            if g[r][c] in skip or (r,c) in found: continue
            col=g[r][c]; st=[(r,c)]; pts=[]
            while st:
                x,y=st.pop()
                if (x,y) in found: continue
                found.add((x,y)); pts.append((x,y))
                for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                    nx,ny=x+dx,y+dy
                    if 0<=nx<h and 0<=ny<w and g[nx][ny]==col and (nx,ny) not in found:
                        st.append((nx,ny))
            rs=[p[0] for p in pts]; cs=[p[1] for p in pts]
            r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
            tot=(r1-r0+1)*(c1-c0+1)
            fill=sum(1 for x in range(r0,r1+1) for y in range(c0,c1+1) if (x,y) in set(pts))
            out.append({'col':col,'bbox':(r0,r1,c0,c1),'n':len(pts),'fillratio':round(fill/tot,3),'pts':set(pts)})
    return out
