def comps_of(g,color):
    h,w=len(g),len(g[0]); seen=set(); res=[]
    for i in range(h):
        for j in range(w):
            if g[i][j]==color and (i,j) not in seen:
                st=[(i,j)]; seen.add((i,j)); pts=[]
                while st:
                    y,x=st.pop(); pts.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        p=(y+dy,x+dx)
                        if 0<=p[0]<h and 0<=p[1]<w and g[p[0]][p[1]]==color and p not in seen:
                            seen.add(p); st.append(p)
                # solid check
                ys=[a for a,b in pts]; xs=[b for a,b in pts]
                minr,maxr,minc,maxc=min(ys),max(ys),min(xs),max(xs)
                solid = (maxr-minr+1)==(maxc-minc+1) and len(pts)==(maxr-minr+1)*(maxc-minc+1)
                res.append((pts,solid,min(minr,minc)))
    return res
